  Item_10086_Name = {
    Text = "След ковенанта (уже устаревший)"
  },
  Item_10087_Desc = {
    Text = "Основной атрибут случайным образом получает один из следующих: критический шанс, критический Урон, Сопротивление смерти и повышенный Урон."
  },
  Item_10087_Name = {
    Text = "Куколка девушки Ⅲ"
  },
  Item_10087_StoryDesc = {
    Text = "Предоставляю вам чистый сосуд."
  },
  Item_10088_Desc = {
    Text = "Это потерянное сознание древней воли. Мисаг пробуждает сознание пробуждённых через мистический ритуал, и пробуждённые, получившие вдохновение, навсегда усиливают свои психические способности.\nПри повторном получении Касии она преобразуется для активации духа Касии."
  },
  Item_10088_Name = {
    Text = "Фрагмент·Касия"
  },
  Item_10088_StoryDesc = {
