  Item_120491_Desc = {
    Text = "Запишите этот ключевой приказ, и вы сможете выбрать навык ключа: «Из Туманного предела».\n\nТа, кто является выдающимся форвардом следственной группы Туманных Земель в том мире, — это она, «Мушетт».\nЭта «Мушетт», прошедшая крещение в серебре и крови в этом мире, также является ею.\nЭтот значок с «ароматом родины» — вечное свидетельство этого путешествия через размерности."
  },
  Item_120491_Name = {
    Text = "Из Туманного предела"
  },
  Item_120491_StoryDesc = {
    Text = "Та, кто является выдающимся форвардом следственной группы Туманных Земель в том мире, — это она, «Мушетт».\n Эта «Мушетт», прошедшая крещение в серебре и крови в этом мире, также является ею.\n Этот значок с «ароматом родины» — вечное свидетельство этого путешествия через размерности."
  },
