  Item_132904_Name = {
    Text = "временный текст"
  },
  Item_132905_Desc = {
    Text = "Кристалл с серебряным ядром, мерцающий хрупким великолепием.\nИногда появляется при многократной очистке серебряного ядра и на определённое время позволяет установить связь с волей высшего существа."
  },
