  Item_51996_Name = {
    Text = "Имя Серебряного Ключа: Лиз"
  },
  Item_51996_StoryDesc = {
    Text = "Запись темы исследования 6-й выпуск"
  },
  Item_52037_Desc = {
    Text = "Предмет для обмена в \"алтарь духа мозга\".\nПредложи свой мозг, о жертвующий. Все желания, божественная страна исполнит."
  },
  Item_52037_Name = {
    Text = "Мозг жреца"
  },
  Item_52038_Desc = {
    Text = "Предмет для обмена в \"Алтаре жертвы крови гориллы\".\nПринеси свою кровь, о жрец. Все грехи будут наказаны божественной страной."
  },
  Item_52038_Name = {
    Text = "Кровь жреца"
  },
  Item_52039_Desc = {
    Text = "Используется для обмена в «Алтарь эрин».\nПринеси свои слезы, Священник. Все страдания будут вознаграждены в царстве бога."
  },
  Item_52039_Name = {
    Text = "Слеза жреца"
  },
  Item_52069_Desc = {
    Text = "Частицы эмоций, рассеянные в Лемурии. При прикосновении словно слышны чья-то Молитва и плач.\nИспользуется для усиления резонанса Хранителя в активности «Рождение Божьего царства».\nМожно получить в качестве награды за достижения в ограниченном событии «Жертвоприношение бездне»."
  },
  Item_52069_Name = {
    Text = "сердце благочестия"
  },
  Item_52070_Desc = {
    Text = "Во время акции \"Жертвоприношение бездне\" получите достижение. \n \"Воля Его всё ещё в спячке в глубоком море... Мы также не должны оставаться позади...\""
  },
  Item_52070_Name = {
    Text = "Во имя серебряного ключа: Мириам"
  },
  Item_52070_StoryDesc = {
    Text = "Акция по игре Мириам"
  },
