  },
  Item_84321_Desc = {
    Text = "«Неплохо, парень!»"
  },
  Item_84321_EmojiName = {
    Text = "Правда"
  },
  Item_84321_Name = {
    Text = "Главы о внеклассных занятиях: Лотан·Хорошо"
  },
  Item_84321_StoryDesc = {
    Text = "17-й выпуск Фазовой ловушки"
  },
  Item_84322_Desc = {
    Text = "«Слышал, что если на выступлении занять такую позу, то зрители очень обрадуются?»"
  },
  Item_84322_EmojiName = {Text = "Мяу"},
  Item_84322_Name = {
